import sys

def repeatedRows(matrix):
    seen = {}
    result = []
    for i, row in enumerate(matrix):
        key = tuple(row)
        if key in seen:
            result.append(i)
        else:
            seen[key] = True
    return result

def main():
    data = sys.stdin.read().split()
    idx = 0
    R = int(data[idx])
    idx += 1
    C = int(data[idx])
    idx += 1
    matrix = []
    for _ in range(R):
        row = []
        for _ in range(C):
            row.append(int(data[idx]))
            idx += 1
        matrix.append(row)

    result = repeatedRows(matrix)
    print(*(result))

if __name__ == "__main__":
    main()
